function table(rows){if(!rows.length)return `<div class="empty"><h3>No records match</h3><p>Try another search or clear the filters.</p>${btn('Clear filters','clear')}</div>`;const exp=(window.itsExport?window.itsExport.renderExportButtons():'<div class="list-export-tools"><span class="export-label">Export:</span><button type="button" class="button small export-btn export-btn-csv" data-action="export-csv" title="Download whole list as CSV">⬇ CSV</button><button type="button" class="button small export-btn export-btn-excel" data-action="export-excel" title="Download whole list as Excel spreadsheet">⬇ Excel</button></div>');return `<div class="table-wrap"><table><thead><tr><th>Record</th><th>Project</th><th>Status</th><th>Owner</th><th>Due date</th><th>Documents</th></tr></thead><tbody>${rows.map(r=>{const label=SCHEMAS[r.type]?.label||r.doctype||r.type;const docType=r.doctype||SCHEMAS[r.type]?.label||'';const docHref=docType?`#record/${encodeURIComponent(docType)}/${encodeURIComponent(r.id)}`:`#record/${encodeURIComponent(r.id)}`;return `<tr><td class="record-col"><a href="${docHref}"><strong>${esc(r.title)}</strong><small>${r.id} · ${esc(label)}</small></a></td><td><a href="#project/${r.project}">${r.project}</a><small>${projectTypeLabel(projectOf(r)?.project_type||'')}</small></td><td>${badge(r.status)}</td><td>${esc(r.owner)}</td><td class="nowrap">${dateText(r.due)}${overdue(r)?'<br><small style="color:#a04132">Overdue</small>':''}</td><td>${r.docs?r.docs.filter(d=>d.state==='Accepted').length:0} / ${r.docs?r.docs.length:0}<br><small>accepted</small></td></tr>`}).join('')}</tbody></table></div><div class="count-line"><span>${rows.length} records · Select a record to open its details.</span>${exp}</div>`}
