let drilldownState = { loading: false, records: [], query: '', project: 'all', status: 'all', params: {} };
function parseHashParams(hashStr) {
	const qIdx = hashStr.indexOf('?');
	const p = new URLSearchParams(qIdx !== -1 ? hashStr.slice(qIdx + 1) : '');
	return {
		key: p.get('key') || '',
		doctype: p.get('doctype') || '',
		status: p.get('status') || '',
		project: p.get('project') || 'all',
		department: p.get('department') || 'all',
		days: Number(p.get('days')) || 30
	};
}
function getDrilldownTitle(params) {
	if (params.status) return `${params.status} Records`;
	if (params.doctype) return `${params.doctype} Records`;
	const titles = {
		'approval': 'Awaiting Approval',
		'overdue': 'Overdue Actions',
		'due': `Due Soon (Next ${params.days || 30} Days)`,
		'returned': 'Returned for Correction',
		'rfi': 'RFIs',
		'inquiry': 'Opportunities & Inquiries',
		'quotation': 'Quotations',
		'order': 'Sales Orders',
		'purchase': 'Purchase Orders',
		'lineItemContract': 'Line Item Contracts',
		'invoice': 'Tax Invoices',
		'proforma': 'Proforma Invoices',
		'creditNote': 'Credit Notes',
		'debitNote': 'Debit Notes',
		'payment': 'Payment Follow-ups',
		'supplierInvoice': 'Supplier Invoices',
		'employee': 'Employee & Manpower Records',
		'timesheet': 'Timesheets',
		'leave': 'Leave Applications',
		'access': 'Site Access Records',
		'dpr': 'Daily Progress Reports',
		'shipment': 'Shipments & Material Receipts',
		'skid': 'PSS Skids',
		'fat': 'FAT Completed Events',
		'ifat': 'IFAT Completed Events',
		'commissioning': 'Commissioned Records',
		'punch_open': 'Open Punch Points',
		'punch_overdue': 'Overdue Punch Points'
	};
	if (params.key && params.key.startsWith('module:')) {
		const modIdx = Number(params.key.split(':')[1]);
		return `${(window.DEPARTMENTS && DEPARTMENTS[modIdx]) || 'Department'} Records`;
	}
	return titles[params.key] || (params.key ? params.key.toUpperCase() : 'All Records');
}
async function drilldownListPage() {
	const params = parseHashParams(route);
	drilldownState.params = params;
	drilldownState.project = params.project || 'all';
	drilldownState.status = params.status || 'all';
	drilldownState.query = '';

	const title = getDrilldownTitle(params);
	const view = $('view');
	if (!view) return;

	view.innerHTML = `
		<div class="crumb">
			<a href="#dashboard">Dashboard</a>
			<span>/</span>
			Drill-down: ${esc(title)}
		</div>
		<div class="page-heading">
			<div>
				<div class="eyebrow">LIVE ERPNEXT DRILL-DOWN</div>
				<h1>${esc(title)}</h1>
				<p>Live matching records from Frappe database. Click any record to inspect exact fields, child tables, attachments and workflow.</p>
			</div>
			<div class="actions">
				<a class="button" href="#dashboard">← Back to Dashboard</a>
			</div>
		</div>
		<section class="panel">
			<div class="toolbar">
				<input id="drilldown-search" type="search" aria-label="Search records" placeholder="Search record, project, owner, status..." value="">
				<select id="drilldown-project" aria-label="Filter by project">
					<option value="all">All projects</option>
					${PROJECTS.map(p => `<option value="${p.id}" ${drilldownState.project === p.id ? 'selected' : ''}>${p.id} · ${p.name}</option>`).join('')}
				</select>
				<select id="drilldown-status" aria-label="Filter by status">
					<option value="all">All statuses</option>
					${['Draft', 'Submitted', 'Returned', 'Approved'].map(s => `<option value="${s}" ${drilldownState.status === s ? 'selected' : ''}>${s}</option>`).join('')}
				</select>
				<button class="button small" id="drilldown-refresh-btn">↻ Refresh</button>
				${window.itsExport ? window.itsExport.renderExportButtons({ title: title }) : '<div class="list-export-tools"><span class="export-label">Export:</span><button type="button" class="button small export-btn export-btn-csv" data-action="export-csv">⬇ CSV</button><button type="button" class="button small export-btn export-btn-excel" data-action="export-excel">⬇ Excel</button></div>'}
			</div>
			<div id="drilldown-records-container">
				<div class="empty" style="padding:50px 20px; text-align:center;">
					<div style="font-size:32px; animation:spin 1.5s linear infinite; margin-bottom:12px;">⏳</div>
					<h3 style="color:#071F4E;">Fetching records from Frappe MariaDB...</h3>
				</div>
			</div>
		</section>
		<p class="footer-note">Every record is loaded directly from MariaDB respecting session permissions.</p>
	`;

	await fetchAndRenderDrilldownRecords();
}
async function fetchAndRenderDrilldownRecords() {
	const container = $('drilldown-records-container');
	if (!container) return;
	drilldownState.loading = true;
	try {
		const p = drilldownState.params;
		const res = await window.frappeDashboardApi.getDrilldownRecords({
			key: p.key,
			doctype: p.doctype,
			status: drilldownState.status !== 'all' ? drilldownState.status : p.status,
			project: drilldownState.project !== 'all' ? drilldownState.project : p.project,
			department: dept !== 'all' ? dept : p.department,
			days: p.days,
			search_text: drilldownState.query
		});
		drilldownState.records = res.records || [];
		renderDrilldownTable();
	} catch (err) {
		container.innerHTML = `
			<div class="empty" style="padding:40px 20px; text-align:center;">
				<h3 style="color:#a04132;">Error loading records</h3>
				<p class="muted">${esc(err.message || 'Failed to fetch drilldown records.')}</p>
				<button class="button primary" style="margin-top:10px;" id="drilldown-retry-btn">Retry</button>
			</div>
		`;
		const retryBtn = $('drilldown-retry-btn');
		if (retryBtn) retryBtn.onclick = () => fetchAndRenderDrilldownRecords();
	} finally {
		drilldownState.loading = false;
	}
}
function renderDrilldownTable() {
	const container = $('drilldown-records-container');
	if (!container) return;
	const q = (drilldownState.query || '').toLowerCase().trim();
	let rows = drilldownState.records;
	if (q) {
		rows = rows.filter(r =>
			`${r.id} ${r.title} ${r.owner} ${r.project} ${r.doctype} ${r.status}`.toLowerCase().includes(q)
		);
	}
	container.innerHTML = table(rows);
}

function readField(label,value,wide=false){return `<div class="field ${wide?'wide':''}"><div class="label">${label}</div><div class="value">${value===0?'0':value?esc(value):'<span class="muted">Not entered</span>'}</div></div>`}
function field(f,value,prefix='f:'){const name=prefix+f.key,input=f.type==='select'?`<select name="${name}">${f.options.map(o=>`<option ${o===value?'selected':''}>${esc(o)}</option>`).join('')}</select>`:f.type==='textarea'?`<textarea name="${name}">${esc(value)}</textarea>`:`<input type="${f.type}" name="${name}" value="${esc(value)}" ${f.type==='number'?'min="0" step="any"':''}>`;return `<label class="field ${f.type==='textarea'?'wide':''}">${f.label}${f.required?' <span class="required">*</span>':''}${input}</label>`}
function items(r,editing){const currency=recordCurrency(r),money=n=>currencyMoney(n,currency);if(!SCHEMAS[r.type].lines)return '';const t=totals(r);const exp=(window.itsExport?window.itsExport.renderExportButtons({title:(r.id||'Document')+'_Items'}):'');return `<div class="split" id="items-editor"><h3 class="section-title">Items & amounts</h3><div class="actions">${!editing&&['Draft','Returned','Approved'].includes(r.status)?btn(r.status==='Approved'?'Edit items (new revision)':'Edit items','edit-items','type="button"','primary'):''}${exp}</div></div><p class="muted">Item Number: line reference (e.g. 1). Material Code: your internal material identifier. Part No.: manufacturer’s part number. ${editing?'Enter these values in the first three columns, then Save draft.':r.status==='Approved'?'Use Edit items (new revision) above to enter your values.':'Select Edit details on a draft to enter these values.'}</p><div class="table-wrap"><table class="line-table"><thead><tr><th>Item Number</th><th>Material Code</th><th>Part No.</th><th>Description</th><th>Qty</th><th>Unit</th><th>Rate (${currency})</th><th>Amount (${currency})</th>${editing?'<th></th>':''}</tr></thead><tbody>${r.lines.map((l,i)=>`<tr>${editing?['itemNumber','code','partNo','description','qty','unit','rate'].map(k=>`<td class="${k==='description'?'description':['qty','rate'].includes(k)?'num':k==='unit'?'unit':''}"><input aria-label="Item ${i+1} ${k==='code'?'Material Code':k==='itemNumber'?'Item Number':k==='partNo'?'Part No.':k}" name="line:${i}:${k}" value="${esc(k==='itemNumber'?(l.itemNumber||String(i+1)):l[k])}" ${['qty','rate'].includes(k)?'type="number" min="0" step="any"':''}></td>`).join(''):`<td>${esc(l.itemNumber||String(i+1))}</td><td>${esc(l.code||'—')}</td><td>${esc(l.partNo||'—')}</td><td>${esc(l.description)}</td><td>${l.qty}</td><td>${esc(l.unit)}</td><td class="amount">${money(l.rate)}</td>`}<td class="amount" id="line-total-${i}">${money(Number(l.qty)*Number(l.rate))}</td>${editing?`<td><button type="button" class="icon-button" data-action="remove-line" data-index="${i}" aria-label="Remove item ${i+1}">×</button></td>`:''}</tr>`).join('')}</tbody></table></div>${editing?btn('+ Add item','add-line','type="button"','small')+btn('Save item changes','save','type="button"','primary'):''}<div class="totals"><div><span>Subtotal</span><strong id="subtotal">${money(t.subtotal)}</strong></div><div><span>Tax ${editing?`<input aria-label="Illustrative tax rate" name="taxRate" type="number" min="0" max="100" step="any" value="${r.taxRate}" style="width:70px;padding:5px">`:`(${r.taxRate}%)`}</span><span id="tax-total">${money(t.tax)}</span></div>${r.type==='invoice'?`<div><span>Retention / recovery / LD</span><span id="deductions-total">− ${money(t.deductions)}</span></div>`:''}<div class="grand"><span>Net amount</span><span id="grand-total">${money(t.total)}</span></div></div><p class="footer-note">Illustrative amounts only. Final tax treatment, deductions and accounting postings require ERPNext configuration.</p>`}
function details(r){if(editDraft){const d=editDraft;return `<form id="record-form" novalidate><div class="fields">${field(F('title','Record title'),d.title,'')}${field(F('owner','Responsible owner'),d.owner,'')}${field(F('due','Due date','date'),d.due,'')}${field(F('priority','Priority','select',true,['Normal','High','Urgent']),d.priority,'')}${SCHEMAS[d.type].fields.map(f=>field(f,d.fields[f.key])).join('')}</div>${items(d,true)}<h3 class="section-title">Internal notes</h3><textarea name="notes" aria-label="Internal notes">${esc(d.notes)}</textarea><div class="form-actions">${btn('Cancel','cancel-edit','type="button"')}${btn('Save draft','save','type="button"','primary')}${btn('Save & submit','save-submit','type="button"')}</div></form>`}return `<div class="fields">${SCHEMAS[r.type].fields.map(f=>readField(f.label,f.type==='date'?dateText(r.fields[f.key]):r.fields[f.key],f.type==='textarea')).join('')}</div>${items(r,false)}${r.notes?`<h3 class="section-title">Internal notes</h3><p style="white-space:pre-wrap">${esc(r.notes)}</p>`:''}`}
function documents(r){return `<h3>Required evidence</h3><p class="muted">${r.docs.filter(d=>d.state==='Accepted').length} of ${r.docs.length} accepted</p>${r.docs.map((d,i)=>`<div class="doc-row"><span class="doc-icon">▤</span><span class="doc-info"><strong>${d.label}</strong><small>${d.reference?esc(d.reference):'No reference recorded'}</small></span>${badge(d.state)}${r.status!=='Approved'?btn('Update','document',`data-index="${i}"`,'small'):''}</div>`).join('')}<div class="notice">Use sample reference numbers to demonstrate receipt and acceptance. Uploaded files appear below. Evidence acceptance is a separate review step.</div>`}
function history(r){return `<h3>Activity & approval history</h3><div class="timeline">${[...r.history].reverse().map(h=>`<div class="event"><strong>${esc(h.action)}</strong><small>${esc(h.actor)} · ${h.time}</small></div>`).join('')}</div><form id="comment-form"><label class="field">Add an internal comment<textarea name="comment" required placeholder="Record a clarification or handover note…"></textarea></label><div class="form-actions"><button class="button primary" type="submit">Add comment</button></div></form>`}
function related(r){const list=records.filter(x=>x.id!==r.id&&(x.id===r.source||x.source===r.id||x.id===r.revisionOf));return `<h3>Directly linked records</h3>${list.length?list.map(taskRow).join(''):'<p>No directly linked records yet.</p>'}<div class="notice info">All records are available in the project workspace.</div><a class="button" href="#project/${r.project}">Open ${r.project} project →</a>`}
function recordPage(id){const r=recordBy(id);if(!r){$('view').innerHTML='<div class="empty"><h1>Record not found</h1><a href="#home">Back to workspace</a></div>';return}const s=SCHEMAS[r.type],n=r.docs.filter(d=>d.state==='Accepted').length,nxt=nextDefinition(r);let actions=editDraft?'':['Draft','Returned'].includes(r.status)?btn('Edit details','edit')+btn('Submit for review','submit','','primary'):r.status==='Submitted'?btn('Return with comments','return')+btn('Approve record','approve','','primary'):btn('Create revision','revise');if(nxt&&!editDraft){actions=`<button class="button primary next-doc-btn" data-action="next" style="background:#F18716; color:#071F4E; border:1px solid #F18716; font-weight:800; display:inline-flex; align-items:center; gap:6px; box-shadow:0 2px 10px rgba(241,135,22,0.35); cursor:pointer;">➔ Create Next: ${esc(nxt.label)}</button>`+actions;}actions+=btn('Print','print');$('view').innerHTML=`<div class="crumb"><a href="#home">Workspace</a><span>/</span><a href="#module/${s.module}">${modules[s.module][0]}</a><span>/</span>${r.id}</div>`+heading(s.label.toUpperCase()+' · '+r.id,r.title||'New '+s.label,`<a href="#project/${r.project}">${r.project} · ${projectOf(r).name}</a> · Revision ${r.revision}`,actions)+(errors.length?`<div class="error-box" role="alert"><strong>Check these items before continuing</strong><ul>${errors.map(e=>`<li>${esc(e)}</li>`).join('')}</ul></div>`:'')+`<div class="record-layout"><section class="panel"><div class="record-summary"><div><div class="label">Status</div>${badge(r.status)}</div>${readField('Responsible owner',r.owner)}${readField('Due date',dateText(r.due))}${readField('Priority',r.priority)}</div><div class="tabs" role="tablist" aria-label="Record sections">${[['details','Details'],['documents','Documents ('+n+'/'+r.docs.length+')'],['history','Activity'],['related','Related records'],['email','Emails']].map(([t,l])=>`<button role="tab" aria-selected="${recordTab===t}" id="tab-${t}" aria-controls="record-tab-panel" data-action="tab" data-tab="${t}" class="${recordTab===t?'active':''}" ${editDraft&&t!=='details'?'disabled':''}>${l}</button>`).join('')}</div><div class="tab-body" id="record-tab-panel" role="tabpanel" aria-labelledby="tab-${recordTab}">${({details,documents,history,related,email:emailRecordTab})[recordTab](r)}</div></section><div class="side-stack"><section class="side-panel" style="border:1.5px solid #F18716; background:linear-gradient(180deg, #FFFFFF 0%, #FFFDF9 100%); box-shadow:0 4px 14px rgba(241,135,22,0.12);"><div class="next-label" style="color:#C25E00; font-weight:800;">NEXT PROCESS STEP (BRD v1.2)</div><h3 style="color:#071F4E; font-weight:800; margin:6px 0;">${nextText(r)}</h3><p style="color:#475569; font-size:13px; line-height:1.45;">${r.status==='Approved'?'This record has completed its approval checks. Proceed to next step.':r.status==='Submitted'?'Review the evidence and approve, or initiate linked draft.':'Complete the details and evidence, or initiate linked draft.'}</p>${nxt?`<button class="button primary" data-action="next" style="width:100%; background:#071F4E; color:#FFFFFF; border:none; padding:10px 14px; font-weight:700; margin-top:8px; cursor:pointer;">➔ Create ${esc(nxt.label)}</button>`:''}<div class="label" style="margin-top:16px">Approval role</div><div class="value" style="font-weight:700; color:#005A9C;">${s.approver}</div></section><section class="side-panel"><h3>Readiness checklist</h3>${[[validation(r).length===0,'Required record details'],[n===r.docs.length,n+' / '+r.docs.length+' documents accepted'],[r.status==='Approved','Reviewer approval']].map(([ok,t])=>`<div class="check ${ok?'':'pending'}"><span class="mark">${ok?'✓':'○'}</span>${t}</div>`).join('')}${r.source?`<div class="label" style="margin-top:20px">Source record</div><a href="#record/${r.source}">${r.source} →</a>`:''}</section><div class="notice compact info">You can try requester and reviewer actions here. The live ERP will enforce user permissions.</div></div></div>`}
function projectsPage(){const skid=route==='skids',trading=route==='trading',list=PROJECTS.filter(p=>skid?(p.kind==='skid'||p.project_type==='POWERSKID'):trading?(p.kind==='supply'||p.project_type==='TRADING'):true);$('view').innerHTML=heading(skid?'SKID PROJECTS':trading?'TRADING PROJECTS':'PROJECT CENTER',skid?'A dedicated workflow for every skid.':trading?'General project operations.':'Different projects. The right workflow.',skid?'Engineering, fabrication, testing and site acceptance in one project area.':trading?'Purchasing, delivery, and sales workflow.':'SKID projects use their own stages. Other project workflows remain separate.')+`<div class="chips"><a class="chip ${!skid&&!trading?'active':''}" href="#projects">All projects</a><a class="chip ${skid?'active':''}" href="#skids">SKID projects</a><a class="chip ${trading?'active':''}" href="#trading">Trading projects</a></div><div class="projects">${list.map(projectCard).join('')}</div><div class="notice">SKID projects have separate equipment and well traceability, fabrication, component FAT, FAT, IFAT, SAT and commissioning. Purchasing, inventory, HR and finance remain connected shared services.</div>`}
function projectPage(id){const p=PROJECTS.find(p=>p.id===id);if(!p){location.hash='projects';return}const list=records.filter(r=>r.project===id),path=projectPath(p);$('view').innerHTML=`<div class="crumb"><a href="#${(p.kind==='skid'||p.project_type==='POWERSKID')?'skids':'projects'}">${(p.kind==='skid'||p.project_type==='POWERSKID')?'SKID projects':'Projects'}</a><span>/</span>${id}</div>`+heading((p.kind==='skid'||p.project_type==='POWERSKID')?'SKID PROJECT / '+id:'PROJECT / '+id,p.name,p.customer,btn('+ Project record','new',`data-project="${id}"`,'primary'))+`<div class="project-meta">${readField('Project manager',p.manager)}${readField('Site',p.site)}${readField('Workflow',(p.kind==='skid'||p.project_type==='POWERSKID')?'SKID integration & commissioning':'Trading / normal project')}${readField((p.kind==='skid'||p.project_type==='POWERSKID')?'Skid / well':'Package reference',(p.kind==='skid'||p.project_type==='POWERSKID')?p.skid+' / '+p.well:p.tag)}</div>${(p.kind==='skid'||p.project_type==='POWERSKID')?`<section class="panel pad" style="margin-bottom:23px"><div class="split"><div><div class="eyebrow">SKID REGISTER</div><h2>${p.skid} · ${p.name}</h2></div><a class="button" href="#record/${list.find(r=>r.type==='skidRegister')?.id||'ITS Review Skid'}">Open skid record →</a></div><div class="fields" style="margin-top:20px">${readField('Well',p.well)}${readField('Equipment tag',p.tag)}${readField('Serial number',p.serial)}${readField('Linked scope','Transformer, VSD, PLC, UPS, HVAC and cabling')}</div></section>`:''}<div class="split" style="margin-bottom:15px"><h2>${(p.kind==='skid'||p.project_type==='POWERSKID')?'SKID execution workflow':'Project workflow'}</h2><span class="muted">${progress(p).n} / ${path.length} stages approved</span></div><div class="workflow-grid">${path.map((step,i)=>{const r=stageRecord(p,step);const dt=r?(r.doctype||SCHEMAS[r.type]?.label||'ITS Review Document'):'';const rHref=r?`#record/${encodeURIComponent(dt)}/${encodeURIComponent(r.id)}`:'';return `<${r?'a href="'+rHref+'"':'div'} class="flow-card ${r?.status==='Approved'?'done':''}"><span class="flow-number">${String(i+1).padStart(2,'0')} →</span><h3>${step.label}</h3><div class="flow-owner">${SCHEMAS[step.type].owner}</div>${r?badge(r.status):btn('+ Create','new',`data-type="${step.type}" data-project="${id}" data-test="${step.test||''}"`,'small')}</${r?'a':'div'}>`}).join('')}</div><div class="notice">${(p.kind==='skid'||p.project_type==='POWERSKID')?'SKID activities can overlap. Each applicable test phase needs its own report, witness acceptance and punch-point clearance.':'Follow the purchasing and sales stages through delivery, invoicing and project closure.'}</div><section class="panel"><div class="panel-head"><div><h2>All project records</h2><span class="sub">Including supporting work</span></div>${window.itsExport?window.itsExport.renderExportButtons({title:id+'_All_Records'}):''}</div>${table(list)}</section>`}
function reportsPage(){const rows=available(),late=rows.filter(overdue),expires=rows.filter(r=>r.fields.expiry&&r.fields.expiry<=dateOffset(30)),invoices=rows.filter(r=>r.type==='invoice'&&r.status==='Approved'),pos=rows.filter(r=>r.type==='purchase'&&r.status==='Approved');$('view').innerHTML=heading('REPORTS & MANAGEMENT','See the exceptions early.','Figures update as you work with the sample records.',btn('Print reports','print'))+`<div class="stats">${stat('Open records',rows.filter(r=>r.status!=='Approved').length,'Operational follow-up')}${stat('Awaiting review',rows.filter(r=>r.status==='Submitted').length,'Submitted records')}${stat('Overdue records',late.length,'Open records past their due date')}${stat('Expiring within 30 days',expires.length,'Contract / permit / warranty dates')}</div><div class="report-grid"><section class="panel pad"><h2>Records by status</h2>${['Draft','Submitted','Returned','Approved'].map(s=>{const n=rows.filter(r=>r.status===s).length;return `<div class="bar-row"><span>${s}</span><div class="bar-track"><span style="width:${n/Math.max(rows.length,1)*100}%"></span></div><strong>${n}</strong></div>`}).join('')}</section><section class="panel"><div class="panel-head"><h2>Upcoming expiry dates</h2></div>${expires.length?expires.map(r=>`<a class="task-row" href="#record/${r.id}"><div class="task-main"><strong>${esc(r.title)}</strong><small>${r.id} · Expires ${dateText(r.fields.expiry)}</small></div><span class="chevron">›</span></a>`).join(''):'<div class="empty"><p>No upcoming expiries.</p></div>'}</section></div><section class="panel" style="margin-top:22px"><div class="panel-head"><h2>Overdue actions</h2></div>${late.length?late.map(taskRow).join(''):'<div class="empty"><p>No overdue records.</p></div>'}</section><p class="footer-note">Prototype summaries only. Ledger balances, payroll, stock valuation and revenue recognition are not calculated here.</p>`}
function guidePage(){$('view').innerHTML=heading('IMPLEMENTATION BRIEF','The ITS ERP, defined for review.','Agree the screens, workflows and acceptance criteria with your ERP provider.',btn('Print implementation brief','print'))+`<div class="notice compact">Interactive design prototype — not an ERPNext installation. All records are illustrative. Check the local database save status. Do not enter real company, payroll or confidential data.</div><div class="guide-grid" style="margin-top:23px"><section class="panel pad"><h2>What you can try</h2><ul><li>${modules.length} department menus and ${Object.keys(SCHEMAS).length} record types with detailed forms.</li><li>Create and edit records, item lines and amounts.</li><li>Submit, approve or return records with comments.</li><li>Record sample document references and acceptance.</li><li>Create the next linked draft from an approved record.</li><li>Separate SKID and other project workflows.</li></ul></section><section class="panel pad"><h2>Dedicated SKID scope</h2><ul><li>Skid, well, project, tag and serial-number register.</li><li>Engineering revisions and equipment interfaces.</li><li>BOM, fabrication and component traceability.</li><li>Component FAT, FAT, IFAT, SAT and punch-point closure.</li><li>Site access, delivery, commissioning and final dossier.</li><li>Shared procurement, stock and finance records.</li></ul></section><section class="panel pad"><h2>Live ERPNext work still required</h2><ul><li>Select hosting; install ERPNext and Frappe HR.</li><li>Classify each requirement as Standard, Configuration or Custom Development for the chosen version.</li><li>Configure company records, users, permissions, authority limits, taxes and accounting.</li><li>Implement document storage, audit logs, notifications and integrations.</li><li>Validate WPS/SIF and UAE finance and payroll requirements.</li><li>Migrate master data and test with ITS staff.</li></ul></section><section class="panel pad"><h2>Try a complete approval</h2><ol><li>Open the metering-package quotation in Approvals.</li><li>Approve it and create its sales order.</li><li>Complete the new record and submit it.</li><li>Try approval before the documents are accepted.</li><li>Add sample references, accept the evidence and approve.</li><li>Review the project and activity history.</li></ol></section></div><div class="notice">Source coverage: the supplied ITS conversation and your instruction to separate SKID projects. Original attachments, approval limits and the previously claimed 473-item list still need reconciliation. PSS and CPE terminology must be confirmed. Document applicability and exceptions must follow each contract.</div><h2 style="margin-top:30px">Detailed department scope</h2>${modules.map((m,i)=>`<section class="panel pad guide-module"><div class="eyebrow">${String(i+1).padStart(2,'0')} / ${DEPARTMENTS[i]}</div><h2>${m[0]}</h2><p style="margin-top:10px">${m[1]}</p>${m[2].map(x=>`<h3>${x[0]}</h3><p>${x[1]}</p>`).join('')}<h3>Record types and fields</h3><ul>${Object.values(SCHEMAS).filter(s=>s.module===i).map(s=>`<li><strong>${s.label}:</strong> ${s.fields.map(f=>f.label).join('; ')}.</li>`).join('')}</ul><h3>Completion check</h3><p>${m[5]}</p></section>`).join('')}<p class="footer-note">Brand: ITS logo, navy #071F4E and orange #F18716. Publishing this prototype does not select hosting for the future ERPNext installation.</p>`}
function render(){nav();if(typeof powerCan==='function'&&!powerCan()&&route.startsWith('record/')&&POWER_ONLY.includes(recordBy(route.split('/')[1])?.type)){powerDashboard();return;}if(route==='dashboard')dashboardPage();else if(route.startsWith('list'))drilldownListPage();else if(route==='home')home();else if(route==='approvals'||route.startsWith('module/'))listPage();else if(route.startsWith('record/')){ if(window.erpDocumentEngine && typeof window.erpDocumentEngine.loadDocument==='function'){ window.erpDocumentEngine.loadDocument(route.slice(7)); } else { recordPage(route.split('/')[1]); } }else if(['projects','skids','trading'].includes(route))projectsPage();else if(route.startsWith('project/'))projectPage(route.split('/')[1]);else if(route==='finance-reports')financeReportsPage();else if(route==='statements')statementPage();else if(route==='outlook')emailPage();else if(route==='reports')reportsPage();else if(route==='guide')guidePage();else if(['clients','suppliers'].includes(route)){if(typeof partyPage==='function')partyPage();else home();}else if(route==='files'){if(typeof filesPage==='function')filesPage();else home();}else if(route==='pss-documents'){if(typeof pssDocumentDirectory==='function')pssDocumentDirectory();else home();}else{route='home';home()}}
function navigate(){const next=location.hash.slice(1)||'dashboard';if(next!==route && $('dialog').open)closeModal();if(next!==route){recordTab='details';editDraft=null;errors=[];filter={type:'all',status:'all',project:'all',query:''}}route=next;document.body.classList.remove('nav-open');render();if(editDraft)document.getElementById('items-editor')?.scrollIntoView({block:'start'});else window.scrollTo(0,0)}
function modal(html){$('dialog-body').innerHTML=html;$('dialog').showModal()}
const closeModal=()=>$('dialog').close(),currentRecord=()=>recordBy(route.split('/')[1]);
function collect(){if(!editDraft||!$('record-form'))return;for(const [key,value]of new FormData($('record-form'))){if(key.startsWith('f:')){const f=SCHEMAS[editDraft.type].fields.find(f=>f.key===key.slice(2));editDraft.fields[f.key]=f.type==='number'?(value===''?'':Number(value)):value}else if(key.startsWith('line:')){const [,i,k]=key.split(':');editDraft.lines[Number(i)][k]=['qty','rate'].includes(k)?Number(value):value}else editDraft[key]=key==='taxRate'?Number(value):value}}
function save(submit){collect();if(!editDraft)return;errors=submit?validation(editDraft):!editDraft.title.trim()?['Enter a record title.']:[];if(errors.length){recordPage(editDraft.id);window.scrollTo(0,0);return}const r=currentRecord();editDraft.history.push({time:stamp(),actor:editDraft.owner,action:'Draft details saved'});Object.assign(r,structuredClone(editDraft));editDraft=null;if(submit)errors=transition(r,'submit');render();notify(submit?'Submitted for review.':'Draft updated. Check the database save status above.')}
function newDialog(el){const {type,module,project,test}=el.dataset,choices=Object.values(SCHEMAS).filter(s=>module!==undefined?s.module===Number(module):dept==='all'||s.module===Number(dept));if(type&&!choices.some(s=>s.key===type))choices.push(SCHEMAS[type]);modal(`<div class="eyebrow">CREATE RECORD</div><h2>Start a new task</h2><p>Choose a record and project. Complete the details on the next screen.</p><form id="new-form" data-test="${test||''}"><div class="fields"><label class="field wide">Record type<select name="type">${choices.map(s=>`<option value="${s.key}" ${type===s.key?'selected':''}>${s.label}</option>`).join('')}</select></label><label class="field wide">Project<select name="project">${PROJECTS.map(p=>`<option value="${p.id}" ${p.id===(project||'ITS-026')?'selected':''}>${p.id} · ${p.name}</option>`).join('')}</select></label></div><div class="form-actions">${btn('Cancel','close','type="button"')}<button class="button primary" type="submit">Create draft →</button></div></form>`)}
function documentDialog(i){const r=currentRecord(),d=r.docs[i];if(r.status==='Approved')return;modal(`<div class="eyebrow">DOCUMENT CHECK</div><h2>${d.label}</h2><p>Use a sample reference to demonstrate the review process.</p><form id="document-form" data-index="${i}"><div class="fields"><label class="field wide">Document reference<input name="reference" value="${esc(d.reference)}" placeholder="e.g. DEMO-SES-024-01"></label><label class="field wide">Review status<select name="state">${['Missing','Received','Accepted'].map(s=>`<option ${s===d.state?'selected':''}>${s}</option>`).join('')}</select></label></div><div id="document-error" role="alert"></div><div class="form-actions">${btn('Cancel','close','type="button"')}<button class="button primary" type="submit">Save document check</button></div></form>`)}
function action(name,el){if(name==='menu'){document.body.classList.toggle('nav-open');return}if(name==='close'||name==='close-dialog'){closeModal();return}if(name==='print'){window.print();return}if(name==='new'){newDialog(el);return}if(name==='clear'){if(route.startsWith('list')){if(typeof drilldownState!=='undefined'){drilldownState.query='';drilldownState.status='all';drilldownState.project='all';const sInp=$('drilldown-search');if(sInp)sInp.value='';const pSel=$('drilldown-project');if(pSel)pSel.value='all';const stSel=$('drilldown-status');if(stSel)stSel.value='all';fetchAndRenderDrilldownRecords();}return;}filter={type:'all',status:'all',project:'all',query:''};render();return}if(name==='filter-type'){filter.type=el.dataset.type;render();return}const r=currentRecord();if(!r)return;if(name==='edit-items'){
if(!['Draft','Returned','Approved'].includes(r.status)){notify('This record is awaiting review. Return it before editing.');return;}
let target=r;if(r.status==='Approved'){target=records.find(n=>n.revisionOf===r.id&&['Draft','Returned'].includes(n.status));if(!target){target=structuredClone(r);target.id=makeRecord(r.type,r.project,r.source).id;target.status='Draft';target.revision=r.revision+1;target.revisionOf=r.id;target.docs.forEach(d=>{if(d.state==='Accepted')d.state='Received'});target.history=[{time:stamp(),actor:r.owner,action:'Editable revision created from '+r.id}];records.push(target);}location.hash='record/'+target.id;route='record/'+target.id;}
editDraft=structuredClone(target);recordTab='details';errors=[];render();document.getElementById('items-editor')?.scrollIntoView({block:'start'});return;}
if(name==='tab'){
if(editDraft)return;recordTab=el.dataset.tab;errors=[];recordPage(r.id)}if(name==='edit'){if(!['Draft','Returned'].includes(r.status))return;editDraft=structuredClone(r);recordTab='details';errors=[];recordPage(r.id)}if(name==='cancel-edit'){editDraft=null;errors=[];recordPage(r.id)}if(name==='save'||name==='save-submit')save(name==='save-submit');if(name==='add-line'||name==='remove-line'){collect();if(name==='add-line')editDraft.lines.push({partNo:'',code:'',description:'',qty:1,unit:'Nos',rate:0});else editDraft.lines.splice(Number(el.dataset.index),1);recordPage(r.id)}if(name==='show-documents'){if(editDraft){notify('Save or cancel the draft before reviewing documents.');return}recordTab='documents';recordPage(r.id)}if(name==='document')documentDialog(Number(el.dataset.index));if(name==='submit'||name==='approve'){errors=transition(r,name);render();if(errors.length)window.scrollTo(0,0);else notify(name==='submit'?'Submitted for review.':'Approved. Project records updated.')}if(name==='return')modal(`<div class="eyebrow">RETURN FOR CHANGES</div><h2>Explain what needs attention</h2><form id="return-form"><label class="field">Comments for the requester<textarea name="reason" required placeholder="Describe the changes needed before approval…"></textarea></label><div class="form-actions">${btn('Cancel','close','type="button"')}<button class="button primary" type="submit">Return record</button></div></form>`);if(name==='next'){const nxt=nextDefinition(r);if(!nxt){notify('No downstream document progression defined for this record type.');return;}if(r.status!=='Approved'){modal(`<div class="eyebrow" style="color:#F18716; font-weight:800;">BRD PROCESS CONFIRMATION</div><h2 style="color:#071F4E; font-weight:800; margin:4px 0 8px 0;">Create Next: ${esc(nxt.label)}</h2><p style="color:#475569; font-size:13px; line-height:1.5;">Source record <strong>${esc(r.id)}</strong> is currently in <strong>${esc(r.status)}</strong> status. In production, approving this document is recommended before downstream processing.</p><div class="notice info" style="margin:14px 0;">All dependencies (project <strong>${esc(r.project)}</strong>, line items, and source link <strong>${esc(r.id)}</strong>) will be inherited into the new draft.</div><div class="form-actions" style="display:flex; justify-content:flex-end; gap:10px; margin-top:16px;"><button type="button" class="button" data-action="close">Cancel</button><button type="button" class="button primary" data-action="confirm-next" style="background:#F18716; color:#071F4E; border-color:#F18716; font-weight:800;">➔ Proceed to Create Draft</button></div>`);return;}try{const n=createNext(r,true);location.hash='record/'+n.id;notify('Linked draft ready. Complete its details before submitting.')}catch(e){notify(e.message)}}if(name==='confirm-next'){try{const n=createNext(r,true);closeModal();location.hash='record/'+n.id;notify('Linked draft created with inherited dependencies.')}catch(e){notify(e.message)}}if(name==='revise'){if(r.status!=='Approved')return;const n=structuredClone(r),fresh=makeRecord(r.type,r.project,r.source);n.id=fresh.id;n.status='Draft';n.revision=r.revision+1;n.revisionOf=r.id;n.history=[{time:stamp(),actor:r.owner,action:'Revision '+n.revision+' created from '+r.id}];n.docs.forEach(d=>{if(d.state==='Accepted')d.state='Received'});records.push(n);location.hash='record/'+n.id;notify('New revision created. The approved original is unchanged.')}}
document.addEventListener('click',e=>{const recordLink=e.target.closest('a[href*="#record/"]');if(recordLink){const dialog=$('dialog');if(dialog&&dialog.open)dialog.close();}if(e.target.id==='drilldown-refresh-btn'||e.target.closest('#drilldown-refresh-btn')){e.preventDefault();if(typeof fetchAndRenderDrilldownRecords==='function')fetchAndRenderDrilldownRecords();return;}const el=e.target.closest('[data-action]');if(el){e.preventDefault();action(el.dataset.action,el)}});
document.addEventListener('input',e=>{if(e.target.id==='drilldown-search'){if(typeof drilldownState!=='undefined'){drilldownState.query=e.target.value;renderDrilldownTable();}return;}if(e.target.id==='search'){filter.query=e.target.value;updateList()}if(e.target.closest('#record-form')&&(e.target.name.startsWith('line:')||e.target.name==='taxRate'||['f:retention','f:recovery','f:ld'].includes(e.target.name))){collect();const money=n=>currencyMoney(n,recordCurrency(editDraft));const t=totals(editDraft);if($('subtotal')){$('subtotal').textContent=money(t.subtotal);$('tax-total').textContent=money(t.tax);$('grand-total').textContent=money(t.total);if($('deductions-total'))$('deductions-total').textContent='− '+money(t.deductions);editDraft.lines.forEach((l,i)=>{if($('line-total-'+i))$('line-total-'+i).textContent=money(Number(l.qty)*Number(l.rate))})}}});
document.addEventListener('change',e=>{if(e.target.id==='drilldown-project'){if(typeof drilldownState!=='undefined'){drilldownState.project=e.target.value;fetchAndRenderDrilldownRecords();}return;}if(e.target.id==='drilldown-status'){if(typeof drilldownState!=='undefined'){drilldownState.status=e.target.value;fetchAndRenderDrilldownRecords();}return;}if(e.target.id==='department'){dept=e.target.value;editDraft=null;errors=[];if(route==='dashboard'||route.startsWith('list'))render();else if(location.hash!=='#home')location.hash='home';else{route='home';render()}}if(e.target.id==='filter-project'){filter.project=e.target.value;if(filter.type!=='all'&&!projectAllows(filter.type,filter.project)&&filter.project!=='all')filter.type='all';listPage()}if(e.target.id==='filter-status'){filter.status=e.target.value;updateList()}});
document.addEventListener('submit',e=>{e.preventDefault();const form=e.target,data=new FormData(form),r=currentRecord();if(form.id==='new-form'){if(!projectAllows(data.get('type'),data.get('project'))){notify('Select a PSS Project for this record type.');return}const n=makeRecord(data.get('type'),data.get('project'));n.title=SCHEMAS[n.type].label;if(n.type==='inspection'&&form.dataset.test)n.fields.testType=form.dataset.test;records.push(n);closeModal();location.hash='record/'+n.id;notify('Draft created. Select Edit details to complete the form.')}if(form.id==='document-form'){const state=data.get('state'),ref=data.get('reference').trim();if(state!=='Missing'&&!ref){$('document-error').textContent='Enter a reference before marking evidence received or accepted.';return}const d=r.docs[Number(form.dataset.index)];d.state=state;d.reference=ref;r.history.push({time:stamp(),actor:r.owner,action:d.label+': '+state+(ref?' · '+ref:'')});closeModal();errors=[];render();notify('Document check updated.')}if(form.id==='return-form'){errors=transition(r,'return',data.get('reason'));if(!errors.length){closeModal();render();notify('Record returned with comments.')}}if(form.id==='comment-form'){const comment=data.get('comment').trim();if(!comment)return;r.history.push({time:stamp(),actor:r.owner,action:'Comment: '+comment});recordPage(r.id);notify('Comment added.')}});

if ($('department')) {
	$('department').innerHTML = '<option value="all">All departments</option>' + DEPARTMENTS.map((d, i) => `<option value="${i}">${d}</option>`).join('');
}
window.addEventListener('hashchange', navigate); navigate();




